// On nettoie et on formatte les données pour le formulaire
return $input.all().map(item => {
  const row = item.json;

  // ⚠️ Remplace par le nom EXACT de tes colonnes dans Baserow
  const capacite = row['Capacité Max'] || 0;
  const inscrits = row['Inscrits Confirmés'] || 0;

  // Calcul du statut complet (true ou false)
  const isComplet = inscrits >= capacite;

  return {
    json: {
      id_atelier: row['ID_Atelier'],
      nom: row["Nom de l'atelier"],
      complet: isComplet
    }
  };
});
